UPDATE aiware.email_template
SET
  code = 
      '"<html xmlns=\"http://www.w3.org/1999/xhtml\">  <head>    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\"/>    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"/>    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>    <title></title>    <link rel=\"stylesheet\" type=\"text/css\" href=\"https://fonts.googleapis.com/css?family=Nunito&display=swap\"/>    <style>      .accept-invitation {        width: auto;      }      @media screen and (max-width: 480px) {        table[style*=\"max-width: 600px\"] {          width: 100% !important;        }        .accept-invitation {          width: 100% !important;          max-width: 100% !important;        }        .accept-invitation td {          width: 100% !important;        }        .accept-invitation a {          width: 100% !important;          display: block !important;        }      }    </style>  </head>  <body>    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: collapse; padding: 0; margin: 0px\">      <tr valign=\"top\">        <td align=\"center\">          <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"              max-width: 600px;              margin: 20px auto;              font-family: Nunito, Helvetica, sans-serif !important;              padding: 40px 0px;            \">            <tr>              <td style=\"padding: 19px 34px\">                <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">                  <tr>                    <td align=\"left\" valign=\"middle\" style=\"width: 50%\">                      <img src=\"https://static.veritone.com/logo/veritone-small-logo-v2.png\" width=\"130\" height=\"25\" style=\"max-width: 100%; height: auto\"/>                    </td>                    <td align=\"right\" valign=\"middle\" style=\"width: 50%\">                      <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" align=\"right\">                        <tr>                          <td title=\"Follow us on X\" style=\"padding-right: 20px\">                            <a href=\"https://twitter.com/veritoneinc\">                              <img src=\"https://get.aiware.com/static/app-icons/X@1x.png\" style=\"display: block\"/>                            </a>                          </td>                          <td title=\"View our GitHub\" style=\"padding-right: 20px\">                            <a href=\"https://github.com/veritone\">                              <img src=\"https://get.aiware.com/static/app-icons/GitHub@1x.png\" style=\"display: block\"/>                            </a>                          </td>                          <td title=\"Connect on LinkedIn\">                            <a href=\"https://www.linkedin.com/company/veritone-inc-/\">                              <img src=\"https://get.aiware.com/static/app-icons/LinkedIn@1x.png\" style=\"display: block\"/>                            </a>                          </td>                        </tr>                      </table>                    </td>                  </tr>                </table>              </td>            </tr>            <tr>              <td style=\"padding: 20px\">                <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"                    border: 1px solid #d5dfe9;                    border-radius: 4px;                    max-width: 560px;                  \">                  <tr>                    <td style=\"padding: 30px\">                      <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">                        <tr>                          <td style=\"font-size: 16px; padding-bottom: 24px\">                            You&apos;ve been invited to join the:                          </td>                        </tr>                        <tr>                          <td style=\"padding-bottom: 24px\">                            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\">                              <tr>                                {{#if organization_icon}}                                <td valign=\"top\" style=\"padding-right: 10px\">                                  <img width=\"40\" height=\"40\" style=\"border-radius: 50%\" src=\"{{organization_icon}}\"/>                                </td>                                {{/if}}                                <td valign=\"middle\">                                  <div style=\"                                      font-weight: 700;                                      font-size: 18px;                                      color: #2a323c;                                    \">                                    {{organization_name}}                                  </div>                                  <div style=\"                                      font-weight: 400;                                      font-size: 12px;                                      color: #5c6269;                                    \">                                    aiWARE Organization                                  </div>                                </td>                              </tr>                            </table>                          </td>                        </tr>                        <tr>                          <td style=\"padding-bottom: 24px\">                            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"max-width: 500px\">                              <tr>                                <td style=\"                                    height: 1px;                                    background-color: #d5dfe9;                                    opacity: 0.9;                                  \"></td>                              </tr>                            </table>                          </td>                        </tr>                        <tr>                          <td style=\"padding-bottom: 30px\">                            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\">                              <tr>                                {{#if requestor_avatar}}                                <td valign=\"top\" style=\"padding-right: 10px\">                                  <img width=\"40\" height=\"40\" style=\"border-radius: 50%\" src=\"{{requestor_avatar}}\"/>                                </td>                                {{else}}                                <td valign=\"top\" style=\"padding-right: 10px\">                                  <div style=\"                                      width: 40px;                                      height: 40px;                                      min-width: 40px;                                      min-height: 40px;                                      background-color: #1565c0;                                      color: #ffffff;                                      font-size: 16px;                                      border-radius: 50%;                                      line-height: 40px;                                      text-align: center;                                    \">                                    {{requestor_shortname}}                                  </div>                                </td>                                {{/if}}                                <td valign=\"middle\">                                  <div style=\"font-size: 16px; color: #2a323c\">                                    <span style=\"font-weight: 700\">{{requestor_name}}                                    </span>                                    has requested that you join the                                    {{organization_name}} aiWARE Organization.                                  </div>                                </td>                              </tr>                            </table>                          </td>                        </tr>                        {{#if optional_message}}                        <tr>                          <td style=\"padding-bottom: 30px\">                            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"                                background-color: #eef3f9;                                border-radius: 4px;                                border-left: 4px solid #0c53b0;                              \">                              <tr>                                <td style=\"padding: 15px 20px\">                                  <div style=\"                                      font-weight: 600;                                      font-size: 16px;                                      color: #0e6eec;                                      margin-bottom: 8px;                                    \">                                    Message:                                  </div>                                  <div style=\"color: #0e6eec; font-size: 16px\">                                    {{optional_message}}                                  </div>                                </td>                              </tr>                            </table>                          </td>                        </tr>                        {{/if}}                        <tr>                          <td style=\"padding-bottom: 30px\">                            <div style=\"font-size: 16px; color: #2a323c\">                              Get started below by creating a login for                              yourself. If you already have an aiWARE user                              account, you can link your existing account                              instead.                            </div>                            <br/>                            <div style=\"font-size: 16px; color: #2a323c\">                              This invitation will be expired in                              <span style=\"font-weight: 600\">{{expiration_date}}</span>.                               If you have any questions, contact                              <a style=\"text-decoration: none\" href=\"{{url_to_support}}\">support@veritone.com</a>.                            </div>                          </td>                        </tr>                        <tr>                          <td>                            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" class=\"accept-invitation\">                              <tr>                                <td align=\"center\" style=\"                                    background-color: #054fa3;                                    border-radius: 4px;                                  \">                                  <a href=\"{{url_acceptable_invitation}}\" style=\"                                      display: inline-block;                                      padding: 0 25px;                                      color: #ffffff;                                      text-decoration: none;                                      font-size: 14px;                                      font-weight: 700;                                      line-height: 40px;                                      text-align: center;                                      width: 100%;                                      box-sizing: border-box;\">Accept Invitation</a>                                </td>                              </tr>                            </table>                          </td>                        </tr>                      </table>                    </td>                  </tr>                </table>              </td>            </tr>            <tr>              <td align=\"center\" style=\"padding-top: 10px\">                <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\">                  <tr>                    <td align=\"center\" valign=\"middle\" style=\"padding-right: 9px\">                      <img src=\"https://get.aiware.com/static/app-icons/VeritoneVLogo@1x.png\" style=\"display: inline-block; vertical-align: middle\"/>                    </td>                    <td align=\"center\" valign=\"middle\" style=\"padding-right: 9px\">                      <span style=\"                          font-size: 12px;                          line-height: 16px;                          color: #5c6269;                          vertical-align: middle;\">© {{year}} Veritone, Inc.</span>                    </td>                    <td align=\"center\" valign=\"middle\" style=\"                        padding-right: 9px;                        font-size: 12px;                        line-height: 16px;                      \">                        <a style=\"color: #0c53b0; display: block\" href=\"{{url_privacy_policy}}\">Privacy Policy</a>                    </td>                    <td align=\"center\" valign=\"middle\" style=\"font-size: 12px; line-height: 16px\">                        <a style=\"color: #0c53b0; display: block\" href=\"{{url_term_service}}\">Terms of Service</a>                    </td>                  </tr>                </table>              </td>            </tr>          </table>        </td>      </tr>    </table>  </body></html>"'::jsonb,
  updated_date = NOW()
WHERE email_template_id = 'new-organization-invitations';
